param([Parameter(Mandatory=$true)][string]$ExportDirectory,[Parameter(Mandatory=$true)][string]$PrivateKeyFile,[string]$ResultDirectory=".verification-backups")
$ErrorActionPreference="Stop";if([string]::IsNullOrWhiteSpace($env:AUDIT_EXPORT_HMAC_KEY)){throw "AUDIT_EXPORT_HMAC_KEY is required"};if([string]::IsNullOrWhiteSpace($env:BACKUP_PRIVATE_KEY_PASSPHRASE)){throw "BACKUP_PRIVATE_KEY_PASSPHRASE is required"}
$project=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot ".."));. (Join-Path $PSScriptRoot 'resolve-node-runtime.ps1');$node=Resolve-PerformanceTrackerNode -ProjectDirectory $project
$export=[IO.Path]::GetFullPath($ExportDirectory);$key=[IO.Path]::GetFullPath($PrivateKeyFile);$manifestPath=Join-Path $export "manifest.json";$signaturePath="$manifestPath.hmac";foreach($path in @($export,$key,$manifestPath,$signaturePath)){if(-not(Test-Path -LiteralPath $path)){throw "Required audit verification input not found: $path"}}
$crypto=Join-Path $PSScriptRoot "backup-crypto.mjs";& $node $crypto verify-hmac $manifestPath $signaturePath;if($LASTEXITCODE-ne0){throw "Audit manifest signature is invalid"};$manifest=Get-Content -LiteralPath $manifestPath -Raw|ConvertFrom-Json;if($manifest.format-ne"performance-tracker-audit-export-v1"){throw "Unsupported audit export format"}
$encrypted=Join-Path $export $manifest.encryptedObject.file;$actual=(Get-FileHash -Algorithm SHA256 -LiteralPath $encrypted).Hash.ToLowerInvariant();if($actual-ne$manifest.encryptedObject.sha256){throw "Encrypted audit object checksum mismatch"};$results=[IO.Path]::GetFullPath((Join-Path $project $ResultDirectory));New-Item -ItemType Directory -Force -Path $results|Out-Null;$plain=Join-Path $results "audit-verify-$([guid]::NewGuid()).jsonl"
try{& $node $crypto decrypt $encrypted $plain $key;if($LASTEXITCODE-ne0){throw "Audit export decryption failed"};$count=0L;$first=$null;$last=$null;Get-Content -LiteralPath $plain|ForEach-Object{$row=$_|ConvertFrom-Json;$id=[long]$row.id;if($last-ne$null-and$id-le$last){throw "Audit rows are missing order or contain duplicate identifiers"};if($row.tenant_id-ne$manifest.tenantId){throw "Audit export contains a different tenant"};if($row.hash_chain_value-notmatch'^[0-9a-f]{64}$'){throw "Audit row is missing its cryptographic chain value"};if($first-eq$null){$first=$id};$last=$id;$count++};if($count-ne[long]$manifest.rowCount-or$first-ne$manifest.firstAuditId-or$last-ne$manifest.lastAuditId){throw "Audit export boundaries do not match its signed manifest"};$result=[ordered]@{status="SUCCESS";export=(Split-Path $export -Leaf);rows=$count;firstAuditId=$first;lastAuditId=$last;verifiedAt=(Get-Date).ToUniversalTime().ToString("o")};$result|ConvertTo-Json -Compress}finally{if(Test-Path -LiteralPath $plain){Remove-Item -LiteralPath $plain}}
